import json, sys
import numpy as np
sys.path.insert(0, ".")
from pacs.profiling.alt_segmentation import segment_by_quantile, to_phase_annotation

def analyze_mpl_impact(model_short):
    """For each problem, re-segment with mpl=5/10/20 and compare phase assignments."""
    dname = f"profiling_output_n500_bf16_{model_short}_imp_s015"
    with open(f"{dname}/profiling_results.json") as f:
        data = json.load(f)

    stored_sp = data["diagnostics"]["per_problem_sparsity"]
    ppi = data["per_problem_ii"]["0.15"]

    results = {mpl: {"n_null_mid": 0, "n_null_low": 0, "n_null_high": 0, 
                      "n_both_valid": 0} for mpl in [5, 10, 20]}

    changed_low_high = {(5, 10): 0, (10, 20): 0, (5, 20): 0}

    for i, sp_entry in enumerate(stored_sp):
        sv = np.array(sp_entry["sparsity_values"])
        if len(sv) < 3:
            continue

        quant_seg = segment_by_quantile(sv, n_groups=3)

        phase_tokens = {}
        for mpl in [5, 10, 20]:
            ann = to_phase_annotation(
                quant_seg.assignments, quant_seg.group_names, sv,
                offset=0, min_phase_length=mpl,
            )
            low_tokens = set()
            mid_tokens = set()
            high_tokens = set()
            for p in ann.phases:
                if p.name == "low_sparsity":
                    low_tokens.update(range(p.start, p.end))
                elif p.name == "mid_sparsity":
                    mid_tokens.update(range(p.start, p.end))
                elif p.name == "high_sparsity":
                    high_tokens.update(range(p.start, p.end))

            phase_tokens[mpl] = {"low": low_tokens, "mid": mid_tokens, "high": high_tokens}

            has_low = len(low_tokens) > 0
            has_mid = len(mid_tokens) > 0
            has_high = len(high_tokens) > 0

            if not has_mid:
                results[mpl]["n_null_mid"] += 1
            if not has_low:
                results[mpl]["n_null_low"] += 1
            if not has_high:
                results[mpl]["n_null_high"] += 1
            if has_low and has_high:
                results[mpl]["n_both_valid"] += 1

        # Check if low/high token sets changed
        for a, b in [(5, 10), (10, 20), (5, 20)]:
            if phase_tokens[a]["low"] != phase_tokens[b]["low"] or \
               phase_tokens[a]["high"] != phase_tokens[b]["high"]:
                changed_low_high[(a, b)] += 1

    print(f"\n=== {model_short.upper()} ===")
    print(f"Total problems: {len(stored_sp)}")
    for mpl in [5, 10, 20]:
        r = results[mpl]
        print(f"mpl={mpl}: null_mid={r['n_null_mid']}, null_low={r['n_null_low']}, "
              f"null_high={r['n_null_high']}, both_valid(low+high)={r['n_both_valid']}")
    print(f"\nLow/High token set changes:")
    for (a, b), n in changed_low_high.items():
        print(f"  mpl={a} vs mpl={b}: {n}/{len(stored_sp)} problems differ")

analyze_mpl_impact("ds")
